"""Human QA wrapper: actual candidate markup, renderer and PetGame, transient synthetic DB only. No PWA registration."""
from pathlib import Path
import re,base64,json,mimetypes,sys
P=Path('.');out=Path(sys.argv[1]) if len(sys.argv)>1 else Path('artifacts/household_v0254c2_teen_human_qa.html');out.parent.mkdir(exist_ok=True,parents=True)
css='\n'.join(Path(n).read_text() for n in ['styles.css','pet-game.css','pet-hq.css','pet-brush.css','pet-ball.css','pet-sleep.css','pet-teen.css','pet-room.css'])
paths={str(p) for p in Path('assets').rglob('*') if p.is_file()};assets={n:{'type':mimetypes.guess_type(n)[0] or 'application/octet-stream','data':base64.b64encode(Path(n).read_bytes()).decode()} for n in sorted(paths)}
boot='''<script>const embeddedAssets=/*ASSETS*/;const blobPaths={};for(const[k,v]of Object.entries(embeddedAssets)){const t=atob(v.data),a=new Uint8Array(t.length);for(let i=0;i<t.length;i++)a[i]=t.charCodeAt(i);blobPaths[k]=URL.createObjectURL(new Blob([a],{type:v.type}));}function mapArtUrls(text){return text.replace(/url\\((['"]?)(?:\\.\\/)?(assets\\/[^)'"\\s]+)\\1\\)/g,(whole,q,path)=>blobPaths[path.split('?')[0]]?'url('+blobPaths[path.split('?')[0]]+')':whole);}const style=document.createElement('style');style.textContent=mapArtUrls(/*CSS*/);document.head.append(style);</script>'''.replace('/*ASSETS*/',json.dumps(assets,separators=(',',':'))).replace('/*CSS*/',json.dumps(css))
html=Path('index.html').read_text();html=re.sub(r'<link rel="(?:manifest|stylesheet)"[^>]+>','',html);html=html.replace('</head>',boot+'''<style>#teenQa{margin:8px auto;padding:10px;max-width:860px;border:1px solid var(--line);border-radius:10px;background:var(--card)}#teenQa select,#teenQa button{min-height:42px;margin:0;width:auto;flex:1;min-width:85px;padding:5px}#teenQa #qaStatus{font-size:11px;flex-basis:100%}#teenQa p{margin:5px 0;font-size:12px}.qa-controls{display:flex;flex-wrap:wrap;gap:4px;align-items:center}</style></head>''',1)
html=html.replace('</header>','''</header><section id="teenQa"><strong>v0.2.54-candidate.2 ローカル統合確認（実データなし）</strong><p>試験専用のメモリDB。家計画面の計算・保存、PWAはこのHTMLの対象外。睡眠確認は短縮モード（待機5〜9秒・睡眠12〜18秒）。</p><div class="qa-controls"><select id="qaSpecies" aria-label="種族"><option value="animal">動物風</option><option value="fantasy">架空の生き物</option><option value="fairy">妖精</option><option value="dino">恐竜</option><option value="yokai">妖怪</option></select><select id="qaStage" aria-label="成長段階"><option value="250">中間体</option><option value="100">幼体</option><option value="1000">成体</option></select><button id="qaReset">再設定</button><button id="qaSleep">ウトウト</button><span id="qaStatus">準備中</span></div></section>''',1)
mock='''window.HAM={};let qaStored=null;const cp=x=>JSON.parse(JSON.stringify(x));const ymd=()=>new Date().toISOString().slice(0,10);HAM.DB={get:async(s,k)=>s==='settings'&&k==='petGameStateV1'&&qaStored?{key:k,value:cp(qaStored)}:null,getAll:async()=>[],put:async(s,x)=>{if(s==='settings'&&x.key==='petGameStateV1')qaStored=cp(x.value);},ymd,currentMonth:()=>ymd().slice(0,7),now:()=>new Date().toISOString(),uid:()=>`qa-${Date.now()}`,prevMonth:s=>s};HAM.Analysis={};'''
scriptfiles=['pet-art.js','pet-illustration.js','sleep-controller.js','teen-art-data.js','pet-teen.js','pet-game.js'];scripts=['<script>'+mock+'</script>']
for name in scriptfiles:
 s=Path(name).read_text()
 if name=='pet-illustration.js':s+="\nconst actualDraw=HAM.PetIllustration.draw;HAM.PetIllustration.draw=options=>mapArtUrls(actualDraw(options));"
 if name=='sleep-controller.js':s+="\nconst normalSleepController=createSleepController;window.__qaShort=true;createSleepController=opts=>{const c=normalSleepController({...opts,short:window.__qaShort});window.__qaController=c;return c;};"
 if name=='pet-teen.js':
  assert "im.src=url+'?v=0254c2'" in s;s=s.replace("im.src=url+'?v=0254c2'","im.src=blobPaths[url]||url+'?v=0254c2'")
 scripts.append('<script>'+s.replace('</script','<\\/script')+'</script>')
qa='''<script>function nav(n){for(const el of document.querySelectorAll('[data-screen]'))el.classList.toggle('active',el.dataset.screen===n);for(const b of document.querySelectorAll('[data-nav]'))b.classList.toggle('active',b.dataset.nav===n);HAM.PetGame.onScreen(n);window.scrollTo(0,0)}function seed(species,pts){const D=HAM.DB,m=D.currentMonth();return {version:2,enabled:true,startedMonth:m,activePet:{id:'qa-only',type:species,name:'確認用の相棒',startedMonth:m,bornAt:D.now(),affection:30,traits:{pet:0,food:0,play:0,calm:0},daily:{date:D.ymd(),used:0,traitsUsed:0}},collection:[],awards:{[m]:{points:Number(pts),bonus:0,items:[],earnedAt:'',petId:'qa-only'}}}}async function reset(species=document.getElementById('qaSpecies').value,pts=Number(document.getElementById('qaStage').value)){document.getElementById('qaStatus').textContent='更新中';await HAM.PetGame.replaceStoredData(async()=>{qaStored=seed(species,pts)});nav('pet');document.getElementById('qaStatus').textContent='実データなし・確認可能'}window.__qa={reset,nav,save:()=>cp(qaStored)};for(const b of document.querySelectorAll('[data-nav]'))b.onclick=()=>nav(b.dataset.nav);document.getElementById('qaReset').onclick=()=>reset();document.getElementById('qaSleep').onclick=()=>{if(HAM.PetGame._test.sleepSnapshot()?.state==='idle')window.__qaController?.forceSleep();};for(const id of ['qaSpecies','qaStage'])document.getElementById(id).onchange=()=>reset();(async()=>{qaStored=seed('animal',250);await HAM.PetGame.init(nav);document.body.classList.remove('app-booting');nav('pet');document.getElementById('qaStatus').textContent='実データなし・確認可能';window.__qaReady=true;})().catch(e=>{document.getElementById('qaStatus').textContent=String(e);console.error(e)});</script>'''
html=re.sub(r'<script src="[^\"]+"\s*></script>','',html);html=html.replace('</body>','\n'.join(scripts)+qa+'</body>');out.write_text(html);print(out, out.stat().st_size)
